import{_ as r,o as a,c as i,a2 as s}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"The driver model","description":"","frontmatter":{},"headers":[],"relativePath":"arch/driver-model.md","filePath":"arch/driver-model.md"}'),t={name:"arch/driver-model.md"};function o(d,e,c,l,n,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="the-driver-model" tabindex="-1">The driver model <a class="header-anchor" href="#the-driver-model" aria-label="Permalink to &quot;The driver model&quot;">​</a></h1><h2 id="registration-surfaces" tabindex="-1">Registration surfaces <a class="header-anchor" href="#registration-surfaces" aria-label="Permalink to &quot;Registration surfaces&quot;">​</a></h2><p>Each family exposes an L1-registration API:</p><ul><li><code>driver_block_register</code> + read/write/flush (+ set_ops) - block devices, per-instance names (ata0, usda, nvme0...)</li><li><code>driver_nic_register</code> + send/recv/link_status/get_mac</li><li><code>driver_snd_register</code> + play/stop/set_rate/set_volume/get_caps</li><li>PCI: <code>driver_pci_find_class_exact/mask</code> for discovery</li></ul><p>A driver probes its bus (PCI IDs, USB descriptors, i2c addresses), claims the device, registers with its family, and from then on the family-level commands and the VFS/socket layers see it uniformly.</p><h2 id="the-pci-core" tabindex="-1">The PCI core <a class="header-anchor" href="#the-pci-core" aria-label="Permalink to &quot;The PCI core&quot;">​</a></h2><p><code>drivers/pci/driver_pci.c</code> + pcie: config-space access, BAR decoding (<code>pcibars</code>), capabilities; MSI where devices use it. <code>lspci</code>, <code>pcidump</code>, <code>pcie</code> inspect from the shell.</p><h2 id="usb-core" tabindex="-1">USB core <a class="header-anchor" href="#usb-core" aria-label="Permalink to &quot;USB core&quot;">​</a></h2><p><code>drivers/usb/driver_usb.c</code> orchestrates four host-controller stacks (UHCI/OHCI/EHCI/xHCI) with device enumeration, hubs to USB_ENUM_DEPTH, and class drivers on top: MSC (mass storage), HID (keyboards/mice), serial, audio. DMA discipline: xHCI refuses above-4GiB addresses at probe and per-transfer.</p><h2 id="error-path-discipline" tabindex="-1">Error-path discipline <a class="header-anchor" href="#error-path-discipline" aria-label="Permalink to &quot;Error-path discipline&quot;">​</a></h2><p>The audit history (BUG-0136..0238) made one thing non-negotiable: a device that lies (truncated table, stuck NAK, garbage response) must be met with a bounded, leak-free unwind. Every probe has a teardown path; every transfer validates its bounds. Bring-up manuals per family: <a href="./../drivers/">../drivers/</a>.</p>',11)])])}const m=r(t,[["render",o]]);export{u as __pageData,m as default};
